510	/// Resolve an absolute path to `(inode number, inode)`.
511	///
512	/// `"/"` is the root, and resolves without a single directory read. Each component
513	/// is looked up through its parent's own entries, so a path naming a file as an
514	/// intermediate component is `ENOTDIR` rather than a read of that file's bytes as
515	/// directory entries — `verify.rs`'s rule.
516	#[cfg_attr(test, allow(dead_code))]
517	fn lookup(blocks: &mut Blocks, mount: &Mount, path: &str) -> Result<(u32, Inode), i32> {
518	    let mut ino = mount.root;
519	    let mut node = read_inode(blocks, mount, ino)?;
520	    for component in walk::components(path) {
521	        if !node.is_dir() {
522	            return Err(ENOTDIR);
