530	/// Find `name` in directory `dir`, streaming one block at a time.
531	///
532	/// `verify.rs` materializes the whole directory into a `Vec` and iterates it;
533	/// there is no allocator here and no second buffer, so this asks about each block
534	/// in turn and keeps nothing but a `u32`. [`walk::dir_size`] is what bounds the
535	/// loop — a corrupt inode claiming `size = i32::MAX` would otherwise spin.
536	#[cfg_attr(test, allow(dead_code))]
537	fn find_component(blocks: &mut Blocks, mount: &Mount, dir: &Inode, name: &str) -> Result<u32, i32> {
538	    let size = walk::dir_size(dir.size)?;
539	    let mut off = 0usize;
540	    while off < size {
541	        let want = (size - off).min(mount.block_size);
542	        if let Some(ino) = scan_block(blocks, mount, dir, off as u64, want, name)? {
543	            return Ok(ino);
544	        }
545	        off += want;
546	    }
547	    Err(ENOENT)
548	}
