565	/// Read up to one chunk of `path` at `pos`, borrowing the bytes out of the block
566	/// buffer.
567	///
568	/// The boot probes' shared machinery. It deliberately stops short of a safecopy —
569	/// there is no second address space involved and no second buffer to copy into —
570	/// so what it proves is the *reader*: lookup, inode decode, zone resolution, and
571	/// one block fetch, over the real image.
572	#[cfg_attr(test, allow(dead_code))]
573	fn read_chunk<'a>(
574	    blocks: &'a mut Blocks,
575	    mount: &Mount,
576	    path: &str,
577	    pos: u64,
578	    len: usize,
579	) -> Result<&'a [u8], i32> {
580	    let (_, node) = lookup(blocks, mount, path)?;
