fn find_component(blocks: &mut Blocks, mount: &Mount, dir: &Inode, name: &str) -> Result<u32, i32> {
    let size = walk::dir_size(dir.size)?;
    let mut off = 0usize;
    while let Some(want) = walk::next_dir_chunk(off, size, mount.block_size) {
